<?php
namespace App\Domain\AI\Runtime\Models;use App\Domain\AI\Agents\Data\AuthorizedAiLifecycleActor;use App\Domain\AI\Runtime\Data\{AgentRuntimeResponseData,ModelResponseData};use App\Domain\AI\Runtime\Enums\RuntimeRunStatus;use App\Domain\AI\Tenancy\AiTenantModel;use Illuminate\Support\Str;
final class RuntimeRun extends AiTenantModel
{protected$table='ai_runtime_runs';protected$guarded=['*'];protected$casts=['status'=>RuntimeRunStatus::class,'needs_handoff'=>'boolean','started_at'=>'datetime','completed_at'=>'datetime','failed_at'=>'datetime'];protected function immutableIdentityAttributes():array{return['uuid','agent_id','agent_version_id','purpose','status','provider_code','model_code','provider_response_id','input_units','cached_input_units','output_units','total_units','estimated_cost_microusd','input_price_microusd_per_million','cached_input_price_microusd_per_million','output_price_microusd_per_million','citation_count','confidence','needs_handoff','handoff_reason','latency_ms','safe_error_code','created_by_user_id','started_at','completed_at','failed_at'];}protected static function booted():void{parent::booted();static::creating(function(self$m){if($m->status!==RuntimeRunStatus::Started)throw new \DomainException('Runtime runs must start in started status.');$m->uuid??=(string)Str::uuid();});}public function isAiAppendOnly():bool{return true;}public function complete(AuthorizedAiLifecycleActor$a,ModelResponseData$m,AgentRuntimeResponseData$r,array$p):void{$this->ensureStarted();$this->assertLifecycleActor($a);$cost=self::cost($m,$p);$this->persistNamedLifecycle($this->mutable(),function()use($m,$r,$p,$cost){$this->status=RuntimeRunStatus::Completed;$this->provider_code='openai';$this->model_code=$m->model;$this->provider_response_id=$m->providerResponseId;$this->input_units=$m->inputUnits;$this->cached_input_units=$m->cachedInputUnits;$this->output_units=$m->outputUnits;$this->total_units=$m->totalUnits;$this->estimated_cost_microusd=$cost;$this->input_price_microusd_per_million=$p['input'];$this->cached_input_price_microusd_per_million=$p['cached_input'];$this->output_price_microusd_per_million=$p['output'];$this->citation_count=count($r->citationIds);$this->confidence=$r->confidence;$this->needs_handoff=$r->needsHandoff;$this->handoff_reason=$r->handoffReason;$this->latency_ms=$m->latencyMilliseconds;$this->completed_at=now();});}public function fail(AuthorizedAiLifecycleActor$a,string$code):void{$this->ensureStarted();$this->assertLifecycleActor($a);if(!in_array($code,['provider_not_configured','provider_authentication','provider_rate_limit','provider_unavailable','provider_timeout','invalid_model_response','runtime_failed'],true))throw new \InvalidArgumentException('Invalid runtime error code.');$this->persistNamedLifecycle($this->mutable(),function()use($code){$this->status=RuntimeRunStatus::Failed;$this->safe_error_code=$code;$this->failed_at=now();});}public function skip(AuthorizedAiLifecycleActor$a):void{$this->ensureStarted();$this->assertLifecycleActor($a);$this->persistNamedLifecycle($this->mutable(),function(){$this->status=RuntimeRunStatus::SkippedNoKnowledge;$this->confidence='low';$this->needs_handoff=true;$this->handoff_reason='insufficient_knowledge';$this->completed_at=now();});}private function ensureStarted():void{if($this->originalAiStatus()!==RuntimeRunStatus::Started->value)throw new \DomainException('Runtime run is terminal.');}private function mutable():array{return array_values(array_diff($this->immutableIdentityAttributes(),['uuid','agent_id','agent_version_id','purpose','created_by_user_id','started_at']));}private static function cost(ModelResponseData$m,array$p):int{$uncached=max(0,$m->inputUnits-$m->cachedInputUnits);return intdiv($uncached*$p['input']+$m->cachedInputUnits*$p['cached_input']+$m->outputUnits*$p['output']+999999,1000000);}}
